import math

class Car:
    def __init__(self, position, velocity):
        self.position = position
        self.velocity = velocity

def calculate_time_to_collision(car1, car2):
    relative_position = car2.position - car1.position
    relative_velocity = car2.velocity - car1.velocity
    time_to_collision = -relative_position / relative_velocity
    return time_to_collision

def determine_collision_point(car1, car2, time_to_collision):
    collision_point = car1.position + car1.velocity * time_to_collision
    return collision_point

def update_car_positions_after_collision(car1, car2):
    car1.position += car1.velocity
    car2.position += car2.velocity

def main():
    cars_set1 = [Car(0, 1), Car(5, -1)]  # Example initial positions and velocities for cars set 1
    cars_set2 = [Car(10, -1), Car(15, 1)]  # Example initial positions and velocities for cars set 2

    while True:
        min_time_to_collision = math.inf
        colliding_cars = None

        for car1 in cars_set1:
            for car2 in cars_set2:
                time_to_collision = calculate_time_to_collision(car1, car2)
                if time_to_collision < min_time_to_collision:
                    min_time_to_collision = time_to_collision
                    colliding_cars = (car1, car2)

        if min_time_to_collision == math.inf:
            break

        collision_point = determine_collision_point(colliding_cars[0], colliding_cars[1], min_time_to_collision)
        update_car_positions_after_collision(colliding_cars[0], colliding_cars[1])

        print(f"Collision occurred at point {collision_point}")

if __name__ == "__main__":
    main()

