    relative_velocity = car2.velocity - car1.velocity

    if relative_velocity == 0:
        return math.inf

    time_to_collision = -relative_position / relative_velocity
    return time_to_collision

def calculate_collision_point(car1, car2, time_to_collision):
    collision_point = car1.position + car1.velocity * time_to_collision
    return collision_point

