            time_to_collision = calculate_time_to_collision(cars[i], cars[j])
            if time_to_collision < first_collision_time:
                first_collision_time = time_to_collision
                first_collision_cars = (cars[i], cars[j])

    return first_collision_time, first_collision_cars

def main():
    car1, car2 = initialize_cars()
    cars = [car1, car2]

